  g+='<line x1="'+X(1915)+'" x2="284" y1="'+Y(30.5)+'" y2="'+Y(30.5)+'" stroke="#2c7a3a" stroke-dasharray="4 3"/>'+T(282,Y(30.5)-4,"balance",'text-anchor="end" font-size="6.6" fill="#2c7a3a" font-weight="700"');
